host_keys')='object' AND (json_type(provenance,'$.host_keys.device_id')='text' AND (typeof(json_extract(provenance,'$.host_keys.device_id'))='text' AND length(json_extract(provenance,'$.host_keys.device_id'))=36 AND length(CAST(json_extract(provenance,'$.host_keys.device_id') AS BLOB))=36 AND json_extract(provenance,'$.host_keys.device_id')=lower(json_extract(provenance,'$.host_keys.device_id')) COLLATE BINARY AND substr(json_extract(provenance,'$.host_keys.device_id'),9,1)='-' AND substr(json_extract(provenance,'$.host_keys.device_id'),14,1)='-' AND substr(json_extract(provenance,'$.host_keys.device_id'),19,1)='-' AND substr(json_extract(provenance,'$.host_keys.device_id'),24,1)='-' AND length(replace(json_extract(provenance,'$.host_keys.device_id'),'-',''))=32 AND replace(json_extract(provenance,'$.host_keys.device_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND json_extract(provenance,'$.host_keys.device_id')<>'00000000-0000-0000-0000-000000000000')) AND (json_type(provenance,'$.host_keys.signing_key')='text' AND typeof(json_extract(provenance,'$.host_keys.signing_key'))='text' AND length(json_extract(provenance,'$.host_keys.signing_key'))=44 AND length(CAST(json_extract(provenance,'$.host_keys.signing_key') AS BLOB))=44 AND substr(json_extract(provenance,'$.host_keys.signing_key'),44,1)='=' AND substr(json_extract(provenance,'$.host_keys.signing_key'),1,43) NOT GLOB '*[^A-Za-z0-9+/]*' AND instr('AEIMQUYcgkosw048',substr(json_extract(provenance,'$.host_keys.signing_key'),43,1))>0) AND (json_type(provenance,'$.host_keys.encryption_key')='text' AND typeof(json_extract(provenance,'$.host_keys.encryption_key'))='text' AND length(json_extract(provenance,'$.host_keys.encryption_key'))=44 AND length(CAST(json_extract(provenance,'$.host_keys.encryption_key') AS BLOB))=44 AND substr(json_extract(provenance,'$.host_keys.encryption_key'),44,1)='=' AND substr(json_extract(provenance,'$.host_keys.encryption_key'),1,43) NOT GLOB '*[^A-Za-z0-9+/]*' AND instr('AEIMQUYcgkosw048',substr(json_extract(provenance,'$.host_keys.encryption_key'),43,1))>0)) AND json_extract(provenance,'$.host_keys.device_id')=peer_device_id COLLATE BINARY AND (json_type(provenance,'$.receiver_epoch')='text' AND (typeof(json_extract(provenance,'$.receiver_epoch'))='text' AND length(json_extract(provenance,'$.receiver_epoch'))=36 AND length(CAST(json_extract(provenance,'$.receiver_epoch') AS BLOB))=36 AND json_extract(provenance,'$.receiver_epoch')=lower(json_extract(provenance,'$.receiver_epoch')) COLLATE BINARY AND substr(json_extract(provenance,'$.receiver_epoch'),9,1)='-' AND substr(json_extract(provenance,'$.receiver_epoch'),14,1)='-' AND substr(json_extract(provenance,'$.receiver_epoch'),19,1)='-' AND substr(json_extract(provenance,'$.receiver_epoch'),24,1)='-' AND length(replace(json_extract(provenance,'$.receiver_epoch'),'-',''))=32 AND replace(json_extract(provenance,'$.receiver_epoch'),'-','') NOT GLOB '*[^0-9a-f]*' AND json_extract(provenance,'$.receiver_epoch')<>'00000000-0000-0000-0000-000000000000')) AND (json_type(provenance,'$.connection_epoch')='text' AND (typeof(json_extract(provenance,'$.connection_epoch'))='text' AND length(json_extract(provenance,'$.connection_epoch'))=36 AND length(CAST(json_extract(provenance,'$.connection_epoch') AS BLOB))=36 AND json_extract(provenance,'$.connection_epoch')=lower(json_extract(provenance,'$.connection_epoch')) COLLATE BINARY AND substr(json_extract(provenance,'$.connection_epoch'),9,1)='-' AND substr(json_extract(provenance,'$.connection_epoch'),14,1)='-' AND substr(json_extract(provenance,'$.connection_epoch'),19,1)='-' AND substr(json_extract(provenance,'$.connection_epoch'),24,1)='-' AND length(replace(json_extract(provenance,'$.connection_epoch'),'-',''))=32 AND replace(json_extract(provenance,'$.connection_epoch'),'-','') NOT GLOB '*[^0-9a-f]*' AND json_extract(provenance,'$.connection_epoch')<>'00000000-0000-0000-0000-000000000000')) AND (json_type(provenance,'$.generation')='null' OR (json_type(provenance,'$.generation')='object' AND (json_type(provenance,'$.generation.grant_id')='text' AND (typeof(json_extract(provenance,'$.generation.grant_id'))='text' AND length(json_extract(provenance,'$.generation.grant_id'))=36 AND length(CAST(json_extract(provenance,'$.generation.grant_id') AS BLOB))=36 AND json_extract(provenance,'$.generation.grant_id')=lower(json_extract(provenance,'$.generation.grant_id')) COLLATE BINARY AND substr(json_extract(provenance,'$.generation.grant_id'),9,1)='-' AND substr(json_extract(provenance,'$.generation.grant_id'),14,1)='-' AND substr(json_extract(provenance,'$.generation.grant_id'),19,1)='-' AND substr(json_extract(provenance,'$.generation.grant_id'),24,1)='-' AND length(replace(json_extract(provenance,'$.generation.grant_id'),'-',''))=32 AND replace(json_extract(provenance,'$.generation.grant_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND json_extract(provenance,'$.generation.grant_id')<>'00000000-0000-0000-0000-000000000000')) AND (json_type(provenance,'$.generation.grant_revision')='integer' AND typeof(json_extract(provenance,'$.generation.grant_revision'))='integer' AND json_extract(provenance,'$.generation.grant_revision')>0) AND (json_type(provenance,'$.generation.host_epoch')='text' AND (typeof(json_extract(provenance,'$.generation.host_epoch'))='text' AND length(json_extract(provenance,'$.generation.host_epoch'))=36 AND length(CAST(json_extract(provenance,'$.generation.host_epoch') AS BLOB))=36 AND json_extract(provenance,'$.generation.host_epoch')=lower(json_extract(provenance,'$.generation.host_epoch')) COLLATE BINARY AND substr(json_extract(provenance,'$.generation.host_epoch'),9,1)='-' AND substr(json_extract(provenance,'$.generation.host_epoch'),14,1)='-' AND substr(json_extract(provenance,'$.generation.host_epoch'),19,1)='-' AND substr(json_extract(provenance,'$.generation.host_epoch'),24,1)='-' AND length(replace(json_extract(provenance,'$.generation.host_epoch'),'-',''))=32 AND replace(json_extract(provenance,'$.generation.host_epoch'