CREATE TABLE settings_transport_private_outbox (
    message_id TEXT PRIMARY KEY NOT NULL,
    reservation_id TEXT NOT NULL UNIQUE,
    local_device_id TEXT NOT NULL,
    peer_device_id TEXT NOT NULL REFERENCES devices(id),
    provenance TEXT NOT NULL,
    family TEXT NOT NULL,
    envelope_bytes INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL,
    FOREIGN KEY(message_id) REFERENCES outbox(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY(message_id) REFERENCES transport_outbox(message_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CHECK((typeof(message_id)='text' AND length(message_id)=36 AND length(CAST(message_id AS BLOB))=36 AND message_id=lower(message_id) COLLATE BINARY AND substr(message_id,9,1)='-' AND substr(message_id,14,1)='-' AND substr(message_id,19,1)='-' AND substr(message_id,24,1)='-' AND length(replace(message_id,'-',''))=32 AND replace(message_id,'-','') NOT GLOB '*[^0-9a-f]*' AND message_id<>'00000000-0000-0000-0000-000000000000')),
    CHECK((typeof(reservation_id)='text' AND length(reservation_id)=36 AND length(CAST(reservation_id AS BLOB))=36 AND reservation_id=lower(reservation_id) COLLATE BINARY AND substr(reservation_id,9,1)='-' AND substr(reservation_id,14,1)='-' AND substr(reservation_id,19,1)='-' AND substr(reservation_id,24,1)='-' AND length(replace(reservation_id,'-',''))=32 AND replace(reservation_id,'-','') NOT GLOB '*[^0-9a-f]*' AND reservation_id<>'00000000-0000-0000-0000-000000000000')),
    CHECK((typeof(local_device_id)='text' AND length(local_device_id)=36 AND length(CAST(local_device_id AS BLOB))=36 AND local_device_id=lower(local_device_id) COLLATE BINARY AND substr(local_device_id,9,1)='-' AND substr(local_device_id,14,1)='-' AND substr(local_device_id,19,1)='-' AND substr(local_device_id,24,1)='-' AND length(replace(local_device_id,'-',''))=32 AND replace(local_device_id,'-','') NOT GLOB '*[^0-9a-f]*' AND local_device_id<>'00000000-0000-0000-0000-000000000000')),
    CHECK((typeof(peer_device_id)='text' AND length(peer_device_id)=36 AND length(CAST(peer_device_id AS BLOB))=36 AND peer_device_id=lower(peer_device_id) COLLATE BINARY AND substr(peer_device_id,9,1)='-' AND substr(peer_device_id,14,1)='-' AND substr(peer_device_id,19,1)='-' AND substr(peer_device_id,24,1)='-' AND length(replace(peer_device_id,'-',''))=32 AND replace(peer_device_id,'-','') NOT GLOB '*[^0-9a-f]*' AND peer_device_id<>'00000000-0000-0000-0000-000000000000')),
    CHECK(local_device_id<>peer_device_id COLLATE BINARY),
    CHECK(family IN ('denial','default','inspection','status')),
    CHECK(typeof(envelope_bytes)='integer' AND envelope_bytes>0 AND envelope_bytes<=CASE family WHEN 'denial' THEN 4096 WHEN 'default' THEN 49152 WHEN 'inspection' THEN 90112 WHEN 'status' THEN 360448 ELSE 0 END),
    CHECK(typeof(created_at)='integer' AND created_at>0),
    CHECK(typeof(expires_at)='integer' AND expires_at>created_at),
