CREATE TRIGGER settings_transport_reply_reservations_immutable BEFORE UPDATE ON settings_transport_reply_reservations
BEGIN
    SELECT RAISE(ABORT,'private reply reservation is immutable') WHERE 1;
END;

CREATE TRIGGER settings_transport_reply_capacity BEFORE INSERT ON settings_transport_reply_reservations
BEGIN
    SELECT RAISE(ABORT,'private reply reservation identity exists') WHERE EXISTS(SELECT 1 FROM settings_transport_reply_reservations WHERE reservation_id=NEW.reservation_id) OR EXISTS(SELECT 1 FROM settings_transport_private_outbox WHERE reservation_id=NEW.reservation_id);
    SELECT RAISE(ABORT,'invalid private reply capacity') WHERE NOT coalesce(typeof(NEW.reserved_bytes)='integer' AND NEW.reserved_bytes BETWEEN 1 AND 360448,0);
    SELECT RAISE(ABORT,'private reply global capacity') WHERE NOT coalesce((SELECT CASE WHEN qc>=128 OR rc>=128 OR qb>33554432 OR rb>33554432 THEN 0 ELSE (typeof(qc)='integer' AND typeof(rc)='integer' AND typeof(qb)='integer' AND typeof(rb)='integer' AND qc>=0 AND rc>=0 AND qb>=0 AND rb>=0 AND qc<=127-rc AND NEW.reserved_bytes<=33554432-qb-rb) END FROM (SELECT count(*) AS qc,coalesce(sum(envelope_bytes),0) AS qb FROM settings_transport_private_outbox) AS q CROSS JOIN (SELECT count(*) AS rc,coalesce(sum(reserved_bytes),0) AS rb FROM settings_transport_reply_reservations) AS r),0);
    SELECT RAISE(ABORT,'private reply peer capacity') WHERE NOT coalesce((SELECT CASE WHEN qc>=16 OR rc>=16 OR qb>8388608 OR rb>8388608 THEN 0 ELSE (typeof(qc)='integer' AND typeof(rc)='integer' AND typeof(qb)='integer' AND typeof(rb)='integer' AND qc>=0 AND rc>=0 AND qb>=0 AND rb>=0 AND qc<=15-rc AND NEW.reserved_bytes<=8388608-qb-rb) END FROM (SELECT count(*) AS qc,coalesce(sum(envelope_bytes),0) AS qb FROM settings_transport_private_outbox WHERE peer_device_id=NEW.peer_device_id) AS q CROSS JOIN (SELECT count(*) AS rc,coalesce(sum(reserved_bytes),0) AS rb FROM settings_transport_reply_reservations WHERE peer_device_id=NEW.peer_device_id) AS r),0);
END;

CREATE TRIGGER settings_transport_private_outbox_capacity BEFORE INSERT ON settings_transport_private_outbox
BEGIN
    SELECT RAISE(ABORT,'private ciphertext reservation was not consumed') WHERE EXISTS(SELECT 1 FROM settings_transport_reply_reservations WHERE reservation_id=NEW.reservation_id);
    SELECT RAISE(ABORT,'private ciphertext global capacity') WHERE NOT coalesce((SELECT CASE WHEN qc>=128 OR rc>=128 OR qb>33554432 OR rb>33554432 THEN 0 ELSE (typeof(qc)='integer' AND typeof(rc)='integer' AND typeof(qb)='integer' AND typeof(rb)='integer' AND qc>=0 AND rc>=0 AND qb>=0 AND rb>=0 AND qc<=127-rc AND NEW.envelope_bytes<=33554432-qb-rb) END FROM (SELECT count(*) AS qc,coalesce(sum(envelope_bytes),0) AS qb FROM settings_transport_private_outbox) AS q CROSS JOIN (SELECT count(*) AS rc,coalesce(sum(reserved_bytes),0) AS rb FROM settings_transport_reply_reservations) AS r),0);
    SELECT RAISE(ABORT,'private ciphertext peer capacity') WHERE NOT coalesce((SELECT CASE WHEN qc>=16 OR rc>=16 OR qb>8388608 OR rb>8388608 THEN 0 ELSE (typeof(qc)='integer' AND typeof(rc)='integer' AND typeof(qb)='integer' AND typeof(rb)='integer' AND qc>=0 AND rc>=0 AND qb>=0 AND rb>=0 AND qc<=15-rc AND NEW.envelope_bytes<=8388608-qb-rb) END FROM (SELECT count(*) AS qc,coalesce(sum(envelope_bytes),0) AS qb FROM settings_transport_private_outbox WHERE peer_device_id=NEW.peer_device_id) AS q CROSS JOIN (SELECT count(*) AS rc,coalesce(sum(reserved_bytes),0) AS rb FROM settings_transport_reply_reservations WHERE peer_device_id=NEW.peer_device_id) AS r),0);
END;

CREATE TRIGGER settings_transport_private_outbox_immutable BEFORE UPDATE ON settings_transport_private_outbox
BEGIN
    SELECT RAISE(ABORT,'private ciphertext provenance is immutable') WHERE 1;
END;

CREATE TRIGGER settings_transport_private_outbox_root BEFORE UPDATE ON outbox
WHEN EXISTS(SELECT 1 FROM settings_transport_private_outbox WHERE message_id=OLD.id)
BEGIN
    SELECT RAISE(ABORT,'private ciphertext root is immutable') WHERE NOT coalesce((NEW.rowid IS OLD.rowid AND NEW.id IS OLD.id COLLATE BINARY AND NEW.device_id IS OLD.device_id COLLATE BINARY AND NEW.envelope IS OLD.envelope AND NEW.created_at IS OLD.created_at AND NEW.delivered_at IS NULL AND typeof(NEW.attempts)='integer' AND NEW.attempts BETWEEN OLD.attempts AND 4294967295 AND typeof(NEW.not_before)='integer' AND NEW.not_before>=OLD.not_before),0);
END;

CREATE TRIGGER outbox_capacity_admission BEFORE INSERT ON outbox
BEGIN
    SELECT RAISE(ABORT,'outbox message identity exists') WHERE EXISTS(SELECT 1 FROM outbox WHERE id=NEW.id);
    SELECT RAISE(ABORT,'new outbox delivery must be pending') WHERE NOT coalesce(NEW.delivered_at IS NULL,0);
    SELECT RAISE(ABORT,'invalid outbox capacity bytes') WHERE NOT coalesce(typeof(NEW.envelope)='blob' AND length(NEW.envelope) BETWEEN 1 AND 2097152,0);
    SELECT RAISE(ABORT,'private outbox ciphertext size') WHERE EXISTS(SELECT 1 FROM settings_transport_private_outbox WHERE message_id=NEW.id AND (envelope_bytes<>length(NEW.envelope) OR peer_device_id<>NEW.device_id COLLATE BINARY));
    SELECT RAISE(ABORT,'outbox global capacity') WHERE NOT EXISTS(SELECT 1 FROM settings_transport_private_outbox WHERE message_id=NEW.id) AND NOT coalesce((SELECT CASE WHEN qc>=1024 OR qb>134217728 THEN 0 ELSE (typeof(qc)='integer' AND typeof(qb)='integer' AND qc>=0 AND qb>=0 AND qc<=1023 AND length(NEW.envelope)<=134217728-qb) END FROM (SELECT count(*) AS qc,coalesce(sum(length(o.envelope)),0) AS qb FROM outbox AS o WHERE o.delivered_at IS NULL AND NOT EXISTS(SELECT 1 FROM settings_transport_private_outbox AS p WHERE p.message_id=o.id)) AS q),0);
    SELECT RAISE(ABORT,'outbox peer capacity') WHERE NOT EXISTS(SELECT 1 FROM settings_transport_private_outbox WHERE message_id=NEW.id) AND NOT coalesce((SELECT CASE WHEN qc>=64 OR qb>16777216 THEN 0 ELSE (typeof(qc)='integer' AND typeof(qb)='integer' AND qc>=0 AND qb>=0 AND qc<=63 AND length(NEW.envelope)<=16777216-qb) END FROM (SELECT count(*) AS qc,coalesce(sum(length(o.envelope)),0) AS qb FROM outbox AS o WHERE o.delivered_at IS NULL AND o.device_id=NEW.device_id AND NOT EXISTS(SELECT 1 FROM settings_transport_private_outbox AS p WHERE p.message_id=o.id)) AS q),0);
END;
